window.KANZEN_N2_SETS = [{"id":"kanzen_01","displayName":"Chuyên đề 1: Ngữ pháp Nguyên nhân & Điều kiện","subtitle":"20 câu • Phân biệt cặp bẫy Mondai 7","badge":"Ngữ pháp","questions":[{"mondai":7,"q":1,"prompt":"毎朝欠かさずウォーキングを続けた(　　)、今年は一度も風邪をひかずに過ごせた。","options":["せいで","おかげで","ばかりに","ことだから"],"answer":2,"word_explain":"〜おかげで (nhờ có...): diễn tả nguyên nhân dẫn đến kết quả tích cực (cả năm không bị cảm). Bẫy: 「せいで」 và 「ばかりに」 dùng cho kết quả tiêu cực/đáng tiếc; 「ことだから」 đi sau danh từ chỉ người để suy đoán dựa trên tính cách.","translation_vi":"Nhờ duy trì việc đi bộ đều đặn mỗi sáng mà năm nay tôi đã trải qua cả năm không bị cảm cúm lần nào."},{"mondai":7,"q":2,"prompt":"昨夜、隣の部屋で遅くまで騒いでいた(　　)、今朝は寝不足で頭がぼんやりしている。","options":["せいで","おかげで","だけに","ばかりか"],"answer":1,"word_explain":"〜せいで (tại vì/do...): diễn tả nguyên nhân dẫn đến kết quả tiêu cực (thiếu ngủ, đầu óc lơ mơ). Bẫy: 「おかげで」 dùng cho kết quả tốt; 「だけに」 nhấn mạnh mức độ tương xứng (chính vì... nên càng...); 「ばかりか」 nghĩa là \"không những... mà còn...\".","translation_vi":"Tại phòng bên cạnh làm ồn đến tận khuya tối qua nên sáng nay tôi thiếu ngủ, đầu óc cứ lơ mơ."},{"mondai":7,"q":3,"prompt":"面接で一言余計なことを言ってしまった(　　)、せっかくの内定を逃してしまった。","options":["おかげで","ばかりに","からには","ものの"],"answer":2,"word_explain":"〜ばかりに (chỉ vì... mà...): nhấn mạnh một nguyên nhân duy nhất dẫn đến kết quả xấu đầy nuối tiếc. Bẫy: 「おかげで」 dùng cho kết quả tích cực; 「からには」 diễn tả quyết tâm (một khi đã...); 「ものの」 mang nghĩa tương phản (mặc dù).","translation_vi":"Chỉ vì lỡ nói thừa một câu trong buổi phỏng vấn mà tôi đã đánh mất suất trúng tuyển quý giá."},{"mondai":7,"q":4,"prompt":"このレストランは予約が半年先まで埋まっている(　　)、料理の味もサービスも最高だった。","options":["せいで","ばかりに","だけに","ものの"],"answer":3,"word_explain":"〜だけに (chính vì... nên quả nhiên/càng...): diễn tả kết quả hoàn toàn tương xứng với tính chất hoặc mức độ của vế trước. Bẫy: 「せいで」 và 「ばかりに」 đều dẫn đến kết quả tiêu cực; 「ものの」 mang nghĩa \"mặc dù\" (trái ngược với vế sau).","translation_vi":"Đúng là nhà hàng đã kín lịch đặt trước tới tận nửa năm, nên cả hương vị món ăn lẫn dịch vụ đều tuyệt vời."},{"mondai":7,"q":5,"prompt":"何事にも几帳面な田中さんの(　　)、明日のプレゼン資料もとっくに完成しているに違いない。","options":["おかげで","せいで","ばかりに","ことだから"],"answer":4,"word_explain":"Nの＋ことだから (vì là tính cách của... nên chắc chắn...): dựa vào đặc điểm quen thuộc của ai đó để đưa ra phán đoán (thường đi với 「に違いない」「はずだ」). Bẫy: 「おかげで」「せいで」「ばかりに」 chỉ nguyên nhân của sự việc đã xảy ra, không dùng để suy đoán dựa trên tính cách.","translation_vi":"Với tính cách cẩn thận trong mọi việc của anh Tanaka, chắc chắn tài liệu thuyết trình ngày mai anh ấy cũng đã hoàn thành từ lâu rồi."},{"mondai":7,"q":6,"prompt":"実際に現地へ行って自分の目で確かめてみ(　　)、この計画が実現可能かどうか判断できない。","options":["ないことには","ないからには","ないばかりに","ないおかげで"],"answer":1,"word_explain":"〜ないことには (nếu không... thì không thể...): nêu điều kiện tiên quyết, vế sau luôn mang nghĩa phủ định hoặc bất khả thi (判断できない). Bẫy: 「ないからには」 mang sắc thái quyết tâm/đương nhiên; 「ないばかりに」 chỉ hậu quả đáng tiếc đã xảy ra.","translation_vi":"Nếu không trực tiếp đến hiện trường và tận mắt kiểm chứng thì không thể phán đoán được kế hoạch này có khả thi hay không."},{"mondai":7,"q":7,"prompt":"何度も失敗を経験し(　　)、成功したときの本当の喜びがわかるものだ。","options":["たばかりに","た上は","てこそ","てばかりは"],"answer":3,"word_explain":"〜てこそ (chỉ khi... mới thực sự...): nhấn mạnh điều kiện cần thiết để đạt được giá trị hay nhận thức ở vế sau. Bẫy: 「た上は」 diễn tả quyết tâm sau khi đã làm gì; 「たばかりに」 chỉ nguyên nhân dẫn tới kết quả xấu.","translation_vi":"Chỉ khi trải qua thất bại nhiều lần thì người ta mới thực sự hiểu được niềm vui khi thành công."},{"mondai":7,"q":8,"prompt":"プロジェクトのリーダーを引き受けた(　　)、最後まで責任を持ってやり遂げるつもりだ。","options":["だけに","上は","ばかりに","せいで"],"answer":2,"word_explain":"〜上は (một khi đã... thì phải/quyết tâm...): nhấn mạnh ý chí, quyết tâm hoặc nghĩa vụ đương nhiên sau khi một sự việc đã được quyết định (やり遂げるつもりだ). Bẫy: 「だけに」 chỉ sự tương xứng; 「ばかりに」 và 「せいで」 chỉ kết quả tiêu cực.","translation_vi":"Một khi đã nhận lời làm trưởng nhóm dự án thì tôi quyết tâm sẽ chịu trách nhiệm hoàn thành đến cùng."},{"mondai":7,"q":9,"prompt":"高いお金を払って留学する(　　)、語学力だけでなく現地の文化もしっかり学びたい。","options":["ばかりに","せいで","わりに","からには"],"answer":4,"word_explain":"〜からには (một khi đã... thì...): biểu thị quyết tâm, mong muốn mạnh mẽ hoặc lời khuyên (学びたい) dựa trên tiền đề ở vế trước. Bẫy: 「わりに」 mang nghĩa tương phản (so với... thì lại...); 「ばかりに」 và 「せいで」 dùng cho hậu quả xấu.","translation_vi":"Một khi đã bỏ ra số tiền lớn để đi du học thì tôi muốn học vững không chỉ ngoại ngữ mà cả văn hóa bản địa nữa."},{"mondai":7,"q":10,"prompt":"一度お客様と約束した(　　)、どんなに忙しくても納期に遅れるわけにはいかない。","options":["以上は","おかげで","ことだから","につれて"],"answer":1,"word_explain":"〜以上は (một khi đã... thì đương nhiên phải...): đồng nghĩa với 「からには」「上は」, đi với vế sau thể hiện trách nhiệm/nghĩa vụ (遅れるわけにはいかない). Bẫy: 「おかげで」 chỉ nguyên nhân tích cực; 「ことだから」 đi sau danh từ chỉ người; 「につれて」 chỉ sự biến đổi song song.","translation_vi":"Một khi đã hứa với khách hàng rồi thì dù bận đến mấy cũng không thể trễ hạn giao hàng được."},{"mondai":7,"q":11,"prompt":"甘いものが嫌いな(　　)が、健康のために最近は控えるようにしている。","options":["わけがない","わけではない","ことはない","はずがない"],"answer":2,"word_explain":"〜わけではない (không hẳn là...): phủ định một phần để tránh hiểu lầm, thường đi với 「〜が、...」 để giải thích lý do thật sự. Bẫy: 「わけがない」「はずがない」 là phủ định hoàn toàn (không đời nào); 「ことはない」 đi với Vる mang nghĩa \"không cần thiết\".","translation_vi":"Không hẳn là tôi ghét đồ ngọt, nhưng vì sức khỏe nên dạo gần đây tôi đang cố gắng hạn chế."},{"mondai":7,"q":12,"prompt":"あんなに練習をさぼっていた彼が、明日のピアノコンクールで優勝できる(　　)。","options":["わけではない","ことはない","とは限らない","わけがない"],"answer":4,"word_explain":"〜わけがない (làm gì có chuyện / không đời nào...): phủ định mạnh mẽ khả năng dựa trên căn cứ rõ ràng (lười luyện tập). Bẫy: 「わけではない」 chỉ phủ định một phần (không hẳn là); 「とは限らない」 nghĩa là \"chưa chắc đã\"; 「ことはない」 nghĩa là \"không cần phải\".","translation_vi":"Cậu ấy lười luyện tập đến thế kia thì làm gì có chuyện giành giải nhất trong cuộc thi piano ngày mai được."},{"mondai":7,"q":13,"prompt":"値段が高いからといって、必ずしも品質が良い(　　)。","options":["わけがない","とは限らない","ことはない","ものだ"],"answer":2,"word_explain":"〜とは限らない (không nhất thiết là / chưa chắc đã...): phủ định tính tuyệt đối, rất hay đi cùng 「必ずしも」「〜からといって」. Bẫy: 「わけがない」 phủ định hoàn toàn (không đời nào tốt); 「ことはない」 nghĩa là không cần; 「ものだ」 mang nghĩa khẳng định chân lý.","translation_vi":"Không phải cứ giá cao thì chất lượng nhất định sẽ tốt."},{"mondai":7,"q":14,"prompt":"大人になると、子どものころに比べて一年が過ぎるのが早く感じられる(　　)。","options":["ものだ","わけがない","ことはない","ばかりだ"],"answer":1,"word_explain":"〜ものだ (vốn dĩ là / thường là thế): diễn tả quy luật tự nhiên, chân lý chung hoặc cảm nhận phổ biến của con người. Bẫy: 「わけがない」 phủ định hoàn toàn (trái nghĩa); 「ことはない」 là không cần phải; 「ばかりだ」 diễn tả xu hướng ngày càng tệ/tăng thêm.","translation_vi":"Khi trưởng thành, người ta thường cảm thấy một năm trôi qua nhanh hơn so với hồi còn nhỏ."},{"mondai":7,"q":15,"prompt":"明日の会議は私が代わりに説明するので、あなたがわざわざ出社する(　　)よ。","options":["わけがない","わけではない","ことはない","とは限らない"],"answer":3,"word_explain":"Vる＋ことはない (không cần phải...): khuyên nhủ hoặc trấn an đối phương rằng không cần thiết làm việc gì. Bẫy: 「わけがない」 (không đời nào); 「わけではない」 (không hẳn là); 「とは限らない」 (chưa chắc đã).","translation_vi":"Cuộc họp ngày mai tôi sẽ giải thích thay cho, nên bạn không cần phải cất công đến công ty đâu."},{"mondai":7,"q":16,"prompt":"後ろの席の人にもはっきり聞こえる(　　)、マイクの音量を少し上げてください。","options":["ために","べく","にしたがって","ように"],"answer":4,"word_explain":"〜ように (để có thể...): chỉ mục đích đi với động từ không chủ ý hoặc thể khả năng (聞こえる) và khi hai vế khác chủ ngữ. Bẫy: 「ために」 và 「べく」 dùng với động từ có chủ ý (意志動詞) và cùng chủ ngữ; 「にしたがって」 diễn tả sự biến đổi song song.","translation_vi":"Xin hãy tăng âm lượng micro lên một chút để những người ngồi hàng ghế sau cũng có thể nghe rõ."},{"mondai":7,"q":17,"prompt":"新しい事業を立ち上げる(　　)、銀行から融資を受けることにした。","options":["ように","ために","にしたがって","せいで"],"answer":2,"word_explain":"〜ために (để...): chỉ mục đích trực tiếp đi với động từ có chủ ý (立ち上げる) và cùng chủ ngữ ở hai vế. Bẫy: 「ように」 dùng cho trạng thái/động từ không chủ ý; 「にしたがって」 chỉ biến đổi theo tỉ lệ; 「せいで」 chỉ nguyên nhân xấu.","translation_vi":"Để khởi nghiệp kinh doanh mới, tôi đã quyết định vay vốn từ ngân hàng."},{"mondai":7,"q":18,"prompt":"我が社は、顧客満足度をさらに向上させる(　　)、新たなサポート体制を導入した。","options":["ように","ばかりに","べく","上は"],"answer":3,"word_explain":"Vる＋べく (nhằm để...): cách nói trang trọng, văn viết của 「〜ために」 (đi với động từ có chủ ý 「向上させる」 và cùng chủ ngữ). Bẫy: 「ように」 không đi với động từ có chủ ý trong ngữ cảnh mục đích trực tiếp trang trọng này; 「ばかりに」 chỉ hậu quả đáng tiếc; 「上は」 nghĩa là \"một khi đã\".","translation_vi":"Công ty chúng tôi đã áp dụng hệ thống hỗ trợ mới nhằm nâng cao hơn nữa mức độ hài lòng của khách hàng."},{"mondai":7,"q":19,"prompt":"標高が高くなる(　　)、気温が下がって風も強くなってきた。","options":["にしたがって","ために","ばかりに","からには"],"answer":1,"word_explain":"〜にしたがって (càng... càng / cùng với việc...): diễn tả hai sự biến đổi diễn ra song song theo một chiều hướng (độ cao tăng → nhiệt độ giảm, gió mạnh lên). Bẫy: 「ために」 chỉ mục đích/nguyên nhân; 「ばかりに」 chỉ hậu quả đáng tiếc; 「からには」 chỉ quyết tâm.","translation_vi":"Càng lên cao, nhiệt độ càng giảm xuống và gió cũng bắt đầu mạnh dần lên."},{"mondai":7,"q":20,"prompt":"試験の日が近づく(　　)、胸の鼓動が早くなり、緊張が高まってきた。","options":["べく","上は","だけに","につれて"],"answer":4,"word_explain":"〜につれて (càng... càng...): diễn tả sự thay đổi tự nhiên kéo theo sự thay đổi khác ở vế sau (ngày thi đến gần → căng thẳng tăng lên). Bẫy: 「べく」 chỉ mục đích (nhằm để); 「上は」 diễn tả quyết tâm; 「だけに」 nhấn mạnh mức độ tương xứng.","translation_vi":"Càng gần đến ngày thi, tim tôi càng đập nhanh hơn và cảm giác căng thẳng cũng tăng lên."}]},{"id":"kanzen_02","displayName":"Chuyên đề 2: Ngữ pháp Bắt buộc, Cảm xúc & Nhấn mạnh","subtitle":"20 câu • Phân biệt cặp bẫy Mondai 7","badge":"Ngữ pháp","questions":[{"mondai":7,"q":1,"prompt":"台風の影響で電車がすべて運休になったため、今日の会議は延期(　　)。","options":["せざるを得ない","するわけにはいかない","しないではいられない","してたまらない"],"answer":1,"word_explain":"「〜ざるを得ない」 (đành phải / buộc lòng phải, dù không muốn) nối với thể ない bỏ ない (riêng する → せざるを得ない). Bẫy: 「〜わけにはいかない」 mang nghĩa ngược (không thể hoãn vì lý do xã hội/đạo đức), còn 「〜ないではいられない」 chỉ thôi thúc cảm xúc tự nhiên nên không hợp với quyết định bắt buộc do hoàn cảnh.","translation_vi":"Do ảnh hưởng của bão mà tất cả tàu điện đều ngừng chạy, nên cuộc họp hôm nay đành phải hoãn lại."},{"mondai":7,"q":2,"prompt":"いくら親友に頼まれても、会社の機密情報を教える(　　)。","options":["ざるを得ない","ないではいられない","にすぎない","わけにはいかない"],"answer":4,"word_explain":"「〜わけにはいかない」 diễn tả việc không thể làm điều gì do quy tắc xã hội, đạo đức hoặc trách nhiệm công việc (chia sau V-る). Bẫy: 「ざるを得ない」 và 「ないではいられない」 đều sai cả cách nối (phải bỏ る/chia ない) lẫn sắc thái nghĩa khẳng định bắt buộc.","translation_vi":"Dù có bị bạn thân nhờ vả đến mấy, tôi cũng không thể tiết lộ thông tin bảo mật của công ty."},{"mondai":7,"q":3,"prompt":"部長から直接招待されたのだから、少し体調が悪くても結婚式に出席(　　)。","options":["するわけにはいかない","しないわけにはいかない","してならない","しかねない"],"answer":2,"word_explain":"「〜ないわけにはいかない」 (không thể không làm) biểu thị nghĩa vụ, phép lịch sự hoặc sức ép xã hội khiến bản thân phải làm. Bẫy: 「するわけにはいかない」 mang nghĩa ngược lại (không thể tham dự); 「しかねない」 mang nghĩa có nguy cơ xảy ra chuyện xấu.","translation_vi":"Vì được trưởng phòng trực tiếp mời nên dù sức khỏe hơi không ổn một chút, tôi cũng không thể không tham dự lễ cưới."},{"mondai":7,"q":4,"prompt":"あんなに悲しいニュースを聞いたら、誰でも涙を流さ(　　)。","options":["ないわけにはいかない","ざるを得ない","ないではいられない","かねる"],"answer":3,"word_explain":"「〜ないではいられない」 diễn tả cảm xúc hoặc hành động bột phát tự nhiên, không thể kiềm chế được (V-ない + ではいられない). Bẫy: 「〜ないわけにはいかない」 và 「〜ざるを得ない」 mang nghĩa bắt buộc do nghĩa vụ xã hội hay hoàn cảnh bên ngoài, không dùng cho phản ứng cảm xúc tự nhiên như rơi nước mắt.","translation_vi":"Nghe tin buồn đến vậy thì ai cũng không thể kìm được nước mắt."},{"mondai":7,"q":5,"prompt":"久しぶりに故郷へ帰れることになって、今から家族に会うのが楽しみで(　　)。","options":["やまない","しかねる","すぎない","たまらない"],"answer":4,"word_explain":"「〜てたまらない」 (vô cùng, không chịu nổi) dùng với tính từ/động từ chỉ cảm giác, cảm xúc mãnh liệt của bản thân (Aな + でたまらない). Bẫy: 「〜てやまない」 chỉ dùng với động từ trang trọng thể hiện mong ước, kính trọng (như 願う, 期待する) chứ không đi với 「楽しみで」.","translation_vi":"Lâu lắm rồi mới được về quê nên ngay từ bây giờ tôi đã mong chờ gặp gia đình vô cùng."},{"mondai":7,"q":6,"prompt":"一人暮らしを始めたばかりの娘が、ちゃんと食事をしているか心配で(　　)。","options":["ならない","やまない","いられない","ほかならない"],"answer":1,"word_explain":"「〜てならない」 diễn tả cảm xúc, suy nghĩ tự nhiên dâng trào mãnh liệt không thể ngăn lại (Aな + でならない). Bẫy: 「〜てやまない」 chỉ dùng cho lời chúc, sự kỳ vọng hay lòng biết ơn mang sắc thái trang trọng, không dùng cho 「心配で」.","translation_vi":"Con gái tôi mới bắt đầu sống một mình nên tôi cứ thấy lo lắng không yên không biết con có ăn uống đàng hoàng không."},{"mondai":7,"q":7,"prompt":"昨日から歯が痛くて(　　)ので、急遽歯医者を予約した。","options":["やまない","かねない","しかたがない","に違いない"],"answer":3,"word_explain":"「〜てしかたがない」 (rất, vô cùng, không chịu nổi) thường đi với cảm giác thể chất (đau, buồn ngủ, ngứa...) hoặc cảm xúc kéo dài (Aい → くてしかたがない). Bẫy: 「〜てやまない」 không dùng cho cảm giác đau đớn thể chất; 「かねない」 và 「に違いない」 sai cách kết nối.","translation_vi":"Từ hôm qua răng đau không chịu nổi nên tôi đã đặt lịch khám nha sĩ gấp."},{"mondai":7,"q":8,"prompt":"卒業生の皆さんの今後のご活躍とご発展を、心より願って(　　)。","options":["たまらない","しかたがない","やまない","ならない"],"answer":3,"word_explain":"「〜てやまない」 (vô cùng, khôn nguôi) là cách nói trang trọng, thường đi cố định với các động từ tích cực như 願う、祈る、期待する、感謝する、尊敬する. Bẫy: 「〜てたまらない」「〜てしかたがない」「〜てならない」 mang tính cảm tính cá nhân, không dùng trong văn phong phát biểu/chúc mừng trang trọng đi với 「心より願って」.","translation_vi":"Tôi xin chân thành cầu chúc cho sự thành công và phát triển hơn nữa trong tương lai của các bạn sinh viên tốt nghiệp."},{"mondai":7,"q":9,"prompt":"今回のプロジェクトが成功したのは、チーム全員が最後まで諦めずに努力した結果(　　)。","options":["にすぎない","にほかならない","どころではない","かねない"],"answer":2,"word_explain":"「〜にほかならない」 (chính là, không gì khác ngoài) dùng để khẳng định mạnh mẽ bản chất hoặc nguyên nhân cốt lõi (N + にほかならない). Bẫy: 「〜にすぎない」 (chỉ là) mang sắc thái đánh giá thấp, trái ngược với ý ca ngợi thành quả nỗ lực của cả nhóm.","translation_vi":"Dự án lần này thành công không gì khác chính là kết quả từ nỗ lực không bỏ cuộc đến phút cuối của toàn bộ nhóm."},{"mondai":7,"q":10,"prompt":"普段は絶対に遅刻しない田中さんがまだ来ていないのだから、何かトラブルがあった(　　)。","options":["にすぎない","わけにはいかない","どころではない","に違いない"],"answer":4,"word_explain":"「〜に違いない」 (chắc chắn là) diễn tả sự phán đoán, suy đoán đầy tự tin của người nói dựa trên căn cứ rõ ràng (thể thông thường + に違いない). Bẫy: 「〜にすぎない」 (chẳng qua chỉ là) không phù hợp với mạch suy luận 「〜のだから」; 「わけにはいかない」 không nối với thể quá khứ た.","translation_vi":"Anh Tanaka bình thường tuyệt đối không đi muộn mà giờ vẫn chưa tới, nên chắc chắn là đã xảy ra rắc rối gì đó rồi."},{"mondai":7,"q":11,"prompt":"現場に残された指紋と防犯カメラの映像から判断すると、犯人は内部の人間である(　　)。","options":["に相違ない","にすぎない","てならない","っこない"],"answer":1,"word_explain":"「〜に相違ない」 (chắc chắn không sai) là dạng văn viết, trang trọng của 「〜に違いない」, thường dùng trong báo cáo, điều tra, luận văn (V-る/である + に相違ない). Bẫy: 「〜にすぎない」 mang nghĩa xem nhẹ (\"chỉ là\"), không hợp với kết luận điều tra.","translation_vi":"Phán đoán từ dấu vân tay để lại hiện trường và hình ảnh camera an ninh, hung thủ chắc chắn không sai lệch là người trong nội bộ."},{"mondai":7,"q":12,"prompt":"彼の意見はあくまで個人的な感想(　　)ので、会社全体の公式見解ではありません。","options":["にほかならない","に相違ない","にすぎない","どころか"],"answer":3,"word_explain":"「〜にすぎない」 (chỉ là, chẳng qua là) dùng để giới hạn hoặc hạ thấp mức độ, giá trị của sự việc, hay đi kèm phó từ 「ただ」「あくまで」. Bẫy: 「〜にほかならない」 nhấn mạnh tầm quan trọng/bản chất duy nhất, trái với mục đích giảm nhẹ để phủ nhận tính chính thức ở vế sau.","translation_vi":"Ý kiến của anh ấy suy cho cùng chỉ là cảm nhận cá nhân chứ không phải quan điểm chính thức của toàn công ty."},{"mondai":7,"q":13,"prompt":"締め切りが明日に迫っているので、今夜はゆっくり映画を見る(　　)。","options":["どころか","どころではない","にすぎない","にほかならない"],"answer":2,"word_explain":"「〜どころではない」 (không phải lúc để..., hoàn cảnh không cho phép làm việc gì) đặt ở cuối câu (V-る/N + どころではない). Bẫy: 「〜どころか」 là liên từ nối hai vế câu (AどころかB), không dùng để kết thúc câu như 「〜どころではない」.","translation_vi":"Hạn chót đã cận kề vào ngày mai rồi nên tối nay chẳng phải lúc để thong thả xem phim đâu."},{"mondai":7,"q":14,"prompt":"節約を心がけているのに、今月は貯金が増える(　　)、赤字になってしまった。","options":["どころではない","ばかりか","ざるを得ない","どころか"],"answer":4,"word_explain":"「AどころかB」 (không những không A mà ngược lại/thậm chí còn B) dùng khi vế sau tương phản hoàn toàn với vế trước. Bẫy kinh điển: 「AばかりかB」 (không chỉ A mà còn B) đòi hỏi hai vế cùng chiều, trong khi 「貯金が増える」 (tiền tăng) và 「赤字になる」 (thâm hụt) hoàn toàn trái ngược nhau.","translation_vi":"Dù đã cố gắng tiết kiệm nhưng tháng này đừng nói là tiền tiết kiệm tăng lên, đằng này còn bị thâm hụt nữa."},{"mondai":7,"q":15,"prompt":"こんなに睡眠不足が続いているのに無理をして運転したら、大きな事故を起こし(　　)。","options":["かねる","かねない","っこない","ぬく"],"answer":2,"word_explain":"「〜かねない」 (có nguy cơ, e rằng có thể dẫn đến kết quả xấu) nối sau V-ます bỏ ます. Bẫy kinh điển: 「〜かねる」 mang nghĩa \"khó lòng làm được / không thể làm\", trái ngược hoàn toàn với 「〜かねない」; 「〜っこない」 mang nghĩa phủ định chắc chắn (\"đời nào lại...\").","translation_vi":"Thiếu ngủ kéo dài thế này mà còn cố lái xe thì rất có nguy cơ gây ra tai nạn lớn đấy."},{"mondai":7,"q":16,"prompt":"申し訳ございませんが、個人情報に関わるご質問にはお答えし(　　)。","options":["かねます","かねません","きれません","ぬきます"],"answer":1,"word_explain":"「〜かねる (かねます)」 diễn tả việc khó lòng làm được hoặc từ chối một cách lịch sự vì lý do quy định/tâm lý (V-ます bỏ ます + かねる). Bẫy: 「お答えしかねません」 (có nguy cơ trả lời) mang nghĩa ngược; 「お答えしきれません」 nghĩa là không thể trả lời hết nổi (sai sắc thái từ chối).","translation_vi":"Thành thật xin lỗi, nhưng chúng tôi khó lòng có thể trả lời các câu hỏi liên quan đến thông tin cá nhân."},{"mondai":7,"q":17,"prompt":"一週間前に練習を始めたばかりの初心者に、あんな難しい曲が弾け(　　)。","options":["かねない","きる","っこない","ぬく"],"answer":3,"word_explain":"「〜っこない」 (chắc chắn không thể nào, đời nào có chuyện...) là cách phủ định mạnh trong khẩu ngữ, nối sau V-ます bỏ ます (弾ける → 弾けっこない). Bẫy: 「弾けかねない」 mang nghĩa có nguy cơ đánh được (ngược nghĩa); 「きる」 và 「ぬく」 không nối với thể khả năng 「弾け」.","translation_vi":"Người mới tập từ một tuần trước thì làm sao mà đánh nổi bản nhạc khó như thế được."},{"mondai":7,"q":18,"prompt":"500ページもある長編小説を、連休の三日間で一気に読み(　　)。","options":["かねた","っこなかった","すぎた","きった"],"answer":4,"word_explain":"「〜きる」 (làm hết sạch, làm đến tận cùng, hoàn toàn) nối sau V-ます bỏ ます (読みきる = đọc hết trọn vẹn). Bẫy: 「読みすぎた」 (đọc quá nhiều) mang sắc thái quá mức/tiêu cực, không diễn tả việc hoàn thành trọn vẹn cuốn sách 500 trang trong kỳ nghỉ như 「読みきった」.","translation_vi":"Tôi đã đọc liền một mạch hết sạch cuốn tiểu thuyết dài tới 500 trang trong ba ngày nghỉ lễ."},{"mondai":7,"q":19,"prompt":"途中で何度も心が折れそうになったが、家族の支えのおかげで最後まで戦い(　　)ことができた。","options":["ぬく","かねる","っこない","にすぎない"],"answer":1,"word_explain":"「〜ぬく」 (làm đến tận cùng dù gặp nhiều khó khăn, gian khổ) nối sau V-ます bỏ ます (戦いぬく = kiên cường chiến đấu đến phút cuối). Bẫy: 「戦いかねる」 (ngần ngại/không thể chiến đấu) và 「戦いっこない」 (chắc chắn không chiến đấu) đều ngược nghĩa với mạch câu.","translation_vi":"Giữa chừng đã có nhiều lúc tưởng chừng gục ngã, nhưng nhờ sự ủng hộ của gia đình mà tôi đã có thể chiến đấu đến tận cùng."},{"mondai":7,"q":20,"prompt":"これだけ明確な証拠を突きつけられては、自分のミスを認め(　　)。","options":["るわけにはいかない","ざるを得ない","かねない","っこない"],"answer":2,"word_explain":"「〜ざるを得ない」 (buộc lòng phải làm dù trong lòng không muốn) nối sau V-ない bỏ ない (認める → 認めざるを得ない). Bẫy: 「認めるわけにはいかない」 (không thể thừa nhận) trái ngược với tiền đề bằng chứng đã quá rõ ràng; 「認めかねない」 (có nguy cơ thừa nhận) sai sắc thái bắt buộc.","translation_vi":"Bị đưa ra bằng chứng rõ ràng đến mức này thì đành phải thừa nhận lỗi sai của bản thân thôi."}]},{"id":"kanzen_03","displayName":"Chuyên đề 3: Ngữ pháp Phạm vi, Đối chiếu & Thời điểm","subtitle":"20 câu • Phân biệt cặp bẫy Mondai 7","badge":"Ngữ pháp","questions":[{"mondai":7,"q":1,"prompt":"遺産相続(　　)、親族同士が何年も争っている。","options":["をめぐって","に関して","にわたって","にかけては"],"answer":1,"word_explain":"「〜をめぐって」diễn tả một vấn đề trung tâm gây ra tranh cãi, xung đột, kiện tụng hay thảo luận (thường đi với 争う・議論する・対立する). Bẫy 「〜に関して」chỉ nêu chủ đề một cách trung lập (\"liên quan đến...\"), không mang sắc thái tranh chấp xoay quanh một vấn đề.","translation_vi":"Xoay quanh chuyện thừa kế tài sản, những người họ hàng đã tranh chấp với nhau suốt nhiều năm."},{"mondai":7,"q":2,"prompt":"この地域では、先週から5日間(　　)激しい雨が降り続き、川の氾濫が心配されている。","options":["をめぐって","を通じて","にわたって","にかけては"],"answer":3,"word_explain":"「〜にわたって」nhấn mạnh phạm vi kéo dài về thời gian, không gian hay số lượng (5日間・全国・数十回). Bẫy 「〜を通じて」dùng cho một chu kỳ thời gian trọn vẹn (一年を通じて・生涯を通じて), không dùng với khoảng thời gian đếm được cụ thể như「5日間」.","translation_vi":"Tại khu vực này, mưa lớn kéo dài suốt 5 ngày từ tuần trước nên người ta lo ngại sông sẽ tràn bờ."},{"mondai":7,"q":3,"prompt":"沖縄は一年(　　)温暖な気候なので、いつ訪れても過ごしやすい。","options":["にわたって","を通じて","に関して","にあたって"],"answer":2,"word_explain":"「〜を通じて」(cùng nghĩa「〜を通して」) diễn tả trạng thái duy trì xuyên suốt toàn bộ một chu kỳ thời gian như「一年を通じて」(quanh năm). Bẫy 「〜にわたって」dùng cho một sự kiện/hành động kéo dài trong một khoảng thời gian cụ thể (ví dụ: 一年にわたって調査する), không dùng cho đặc điểm khí hậu lặp lại quanh năm.","translation_vi":"Okinawa có khí hậu ấm áp suốt cả năm nên dù đến thăm vào lúc nào cũng dễ chịu."},{"mondai":7,"q":4,"prompt":"彼は普段はおとなしいが、プログラミングの技術(　　)、社内で右に出る者はいない。","options":["をめぐって","にわたって","にかけては","に関して"],"answer":3,"word_explain":"「〜にかけては」dùng để nêu một lĩnh vực mà đối tượng có năng lực hoặc chất lượng vượt trội, vế sau luôn là đánh giá tích cực (右に出る者はいない・自信がある). Bẫy 「〜に関して」chỉ mang nghĩa trung lập \"về/liên quan đến\", không nhấn mạnh ưu thế vượt trội.","translation_vi":"Bình thường anh ấy khá trầm tính, nhưng xét về kỹ năng lập trình thì trong công ty không ai sánh bằng."},{"mondai":7,"q":5,"prompt":"この博物館には、浮世絵(　　)、江戸時代の貴重な資料が数多く展示されている。","options":["をはじめ","はもとより","を問わず","のみならず"],"answer":1,"word_explain":"「N1をはじめ、N2」nêu N1 làm ví dụ tiêu biểu nhất trong nhóm N2. Bẫy 「〜はもとより」và「〜のみならず」thường đòi hỏi trợ từ「も」ở vế sau (N1はもとよりN2も) và mang nghĩa mở rộng \"không chỉ A mà cả B\", không khớp với「〜が」trong câu này; còn「〜を問わず」dùng với danh từ chỉ tiêu chuẩn/cặp đối lập.","translation_vi":"Tại bảo tàng này, tiêu biểu là tranh Ukiyo-e, còn có rất nhiều tư liệu quý giá thời Edo được trưng bày."},{"mondai":7,"q":6,"prompt":"このボランティア活動は、経験の有無(　　)、やる気のある方を募集しています。","options":["をはじめ","に限らず","はもとより","を問わず"],"answer":4,"word_explain":"「〜を問わず」mang nghĩa \"không phân biệt, không xét đến\", thường đi với danh từ chỉ tiêu chuẩn hoặc cặp đối lập như「年齢・性別・経験の有無・昼夜」. Bẫy 「〜に限らず」nghĩa là \"không chỉ giới hạn ở A (mà còn B)\", không kết hợp với cặp đối lập「有無」(có hay không).","translation_vi":"Hoạt động tình nguyện này tuyển những người có nhiệt huyết, không phân biệt có kinh nghiệm hay chưa."},{"mondai":7,"q":7,"prompt":"このアニメは子ども(　　)、大人にも幅広い人気を集めている。","options":["を問わず","に限らず","をめぐって","にわたって"],"answer":2,"word_explain":"「〜に限らず」nghĩa là \"không chỉ riêng A mà còn mở rộng ra phạm vi lớn hơn (Bも)\". Bẫy 「〜を問わず」không đi sau một đối tượng đơn lẻ như「子ども」, mà phải đi với danh từ chỉ phạm trù chung như「年齢を問わず」(không phân biệt tuổi tác).","translation_vi":"Bộ anime này không chỉ giới hạn ở trẻ em mà còn thu hút sự yêu thích rộng rãi của cả người lớn."},{"mondai":7,"q":8,"prompt":"この仕事をするには、専門知識(　　)、高いコミュニケーション能力も求められる。","options":["をはじめ","を問わず","はもとより","にかけては"],"answer":3,"word_explain":"「N1はもとより、N2も」nhấn mạnh N1 là điều hiển nhiên, không cần bàn cãi, và N2 cũng cần thiết/đúng như vậy. Bẫy 「〜をはじめ」chỉ dùng khi N1 là ví dụ tiêu biểu thuộc tập hợp N2, nhưng ở đây kiến thức chuyên môn và kỹ năng giao tiếp là hai yêu cầu độc lập.","translation_vi":"Để làm công việc này, kiến thức chuyên môn là điều đương nhiên, mà còn đòi hỏi cả khả năng giao tiếp tốt."},{"mondai":7,"q":9,"prompt":"新しい支店を開設する(　　)、地域の皆様に心より感謝申し上げます。","options":["に先立って","最中に","うちに","にあたって"],"answer":4,"word_explain":"「〜にあたって」mang nghĩa trang trọng \"nhân dịp / khi bắt đầu (một sự kiện, cột mốc quan trọng)\", rất hay dùng trong bài phát biểu khai mạc, lời cảm ơn. Bẫy 「〜に先立って」nhấn mạnh trình tự hành động xảy ra \"trước khi\" sự kiện chính diễn ra, không dùng cho lời cảm ơn nhân dịp sự kiện.","translation_vi":"Nhân dịp khai trương chi nhánh mới, tôi xin gửi lời cảm ơn chân thành từ đáy lòng tới quý bà con trong khu vực."},{"mondai":7,"q":10,"prompt":"映画の一般公開(　　)、特別試写会が開かれた。","options":["に先立って","にあたって","をめぐって","を通じて"],"answer":1,"word_explain":"「〜に先立って」diễn tả một hành động/sự kiện diễn ra \"trước khi\" sự kiện chính bắt đầu (ví dụ: chiếu thử trước ngày công chiếu). Bẫy 「〜にあたって」chỉ mang nghĩa \"nhân dịp / khi thực hiện\", không thể hiện rõ trình tự thời gian diễn ra trước đó.","translation_vi":"Trước khi bộ phim được công chiếu rộng rãi, một buổi chiếu thử đặc biệt đã được tổ chức."},{"mondai":7,"q":11,"prompt":"お帰りの(　　)は、お忘れ物のないようお気をつけください。","options":["最中","際","うち","とたん"],"answer":2,"word_explain":"「〜際(に/は)」là cách nói trang trọng, lịch sự của「とき」, thường dùng trong thông báo, hướng dẫn (お帰りの際は・ご利用の際は). Bẫy 「最中」nghĩa là \"đang giữa lúc (thì có chuyện xen ngang)\", còn「とたん」chỉ nối sau V-た chứ không nối sau「の」.","translation_vi":"Khi ra về, quý khách vui lòng chú ý để không bỏ quên đồ đạc."},{"mondai":7,"q":12,"prompt":"このスープは冷めない(　　)、早く召し上がってください。","options":["最中に","うちに","際に","とたんに"],"answer":2,"word_explain":"「〜ないうちに」diễn tả việc tranh thủ làm gì trước khi trạng thái hiện tại thay đổi (lúc chưa nguội). Bẫy 「最中に」「際に」「とたんに」đều không kết hợp với thể phủ định「〜ない」để mang nghĩa \"tranh thủ trước khi...\".","translation_vi":"Xin hãy dùng nhanh món súp này khi còn nóng (lúc chưa bị nguội)."},{"mondai":7,"q":13,"prompt":"大切な会議をしている(　　)、突然停電になって会場が真っ暗になった。","options":["うちに","にあたって","最中に","に先立って"],"answer":3,"word_explain":"「〜最中に」diễn tả đúng lúc hành động đang ở cao trào thì xảy ra sự việc bất ngờ xen ngang (thường là việc ngoài ý muốn). Bẫy 「〜ているうちに」dùng cho sự thay đổi diễn ra tự nhiên, từ từ trong quá trình làm gì, không dùng cho sự cố đột ngột như mất điện.","translation_vi":"Đúng lúc đang tiến hành cuộc họp quan trọng thì đột nhiên mất điện khiến cả hội trường tối om."},{"mondai":7,"q":14,"prompt":"立ち上がった(　　)、激しいめまいがしてその場に座り込んでしまった。","options":["とたん","かと思うと","うちに","最中に"],"answer":1,"word_explain":"「V-た + とたん(に)」diễn tả ngay khoảnh khắc hành động A vừa xảy ra thì hiện tượng bất ngờ, không kiểm soát được B lập tức xảy đến. Bẫy 「〜かと思うと」dùng khi hai sự việc nối tiếp nhanh hoặc trái ngược nhau (thường quan sát khách quan), ít dùng cho phản ứng cơ thể tức thì ngay sau một động tác đơn lẻ của bản thân.","translation_vi":"Vừa đứng dậy một cái là tôi bị chóng mặt dữ dội và ngồi thụp xuống ngay tại chỗ."},{"mondai":7,"q":15,"prompt":"さっきまで気持ちよく晴れていた(　　)、急に空が暗くなって大雨が降り出した。","options":["とたん","最中に","にあたって","かと思うと"],"answer":4,"word_explain":"「〜たかと思うと」diễn tả sự biến đổi cực nhanh và bất ngờ (\"vừa mới thấy A đó mà thoắt cái đã B\"). Bẫy 「〜たとたん」không kết hợp với động từ trạng thái kéo dài「晴れていた」, mà chỉ đi sau động từ chỉ hành động/biến đổi tức thời (開けた・出た・立った).","translation_vi":"Mới vừa nãy còn thấy trời nắng đẹp dễ chịu, thoắt cái bầu trời đã tối sầm lại và mưa như trút nước."},{"mondai":7,"q":16,"prompt":"高価なカメラを買った(　　)、使い方が難しくてまだほとんど使っていない。","options":["つつも","反面","ものの","くせに"],"answer":3,"word_explain":"「〜ものの」diễn tả sự nhượng bộ \"tuy là A nhưng thực tế lại không như kỳ vọng (B)\". Bẫy 「〜つつも」chỉ nối sau V-ます; 「〜反面」dùng để nêu hai mặt đối lập của cùng một tính chất/đối tượng; còn「〜くせに」mang sắc thái chê trách người khác.","translation_vi":"Tuy đã mua một chiếc máy ảnh đắt tiền, nhưng vì cách sử dụng khó nên tôi vẫn hầu như chưa dùng đến."},{"mondai":7,"q":17,"prompt":"体によくないと(　　)、つい夜更かしをしてしまう。","options":["知りつつも","知ったくせに","知ったとたん","知るわりに"],"answer":1,"word_explain":"「V-ます + つつも」diễn tả mâu thuẫn nội tâm: dù biết/nghĩ như vậy nhưng vẫn làm hành động trái ngược (rất hay đi với 知りつつも・思いながらも). Bẫy 「〜くせに」mang sắc thái chỉ trích gay gắt người khác, không dùng để tự nhận khuyết điểm của bản thân.","translation_vi":"Dù biết là không tốt cho sức khỏe nhưng tôi vẫn cứ lỡ thức khuya."},{"mondai":7,"q":18,"prompt":"この仕事は給料が高い(　　)、責任も重く残業が多い。","options":["わりに","くせに","にもかかわらず","反面"],"answer":4,"word_explain":"「〜反面」dùng để đối chiếu hai mặt trái ngược (ưu điểm và nhược điểm) của cùng một đối tượng (tương tự「〜一方で」). Bẫy 「〜わりに」dùng khi kết quả trái với tiêu chuẩn dự đoán, còn「〜にもかかわらず」(\"mặc dù\") sai logic vì lương cao vốn thường đi kèm trách nhiệm cao.","translation_vi":"Công việc này lương cao, nhưng mặt khác trách nhiệm cũng nặng nề và phải tăng ca nhiều."},{"mondai":7,"q":19,"prompt":"あのレストランは駅前の好立地にある(　　)、値段がとても安い。","options":["くせに","わりに","反面","最中に"],"answer":2,"word_explain":"「〜わりに」mang nghĩa \"so với tiêu chuẩn A thì kết quả B khác hẳn dự đoán\" (vị trí đẹp thường đắt, nhưng ở đây lại rẻ). Bẫy 「〜反面」nêu hai mặt tốt – xấu đối lập nhau, trong khi ở câu này cả \"vị trí đẹp\" và \"giá rẻ\" đều là ưu điểm; còn「〜くせに」chỉ dùng chê trách người.","translation_vi":"Nhà hàng kia so với việc nằm ở vị trí đắc địa ngay trước nhà ga thì giá cả lại rất rẻ."},{"mondai":7,"q":20,"prompt":"朝からひどい雨が降っている(　　)、コンサート会場には大勢のファンが集まった。","options":["にもかかわらず","くせに","反面","うちに"],"answer":1,"word_explain":"「〜にもかかわらず」diễn tả sự tương phản mạnh, kết quả xảy ra bất chấp điều kiện bất lợi ở vế trước (\"mặc dù...\"). Bẫy 「〜くせに」chỉ dùng với chủ ngữ là người và mang hàm ý chê trách, không dùng cho hiện tượng thời tiết「雨が降っている」.","translation_vi":"Mặc dù từ sáng trời đã mưa tầm tã, rất đông người hâm mộ vẫn tụ tập tại địa điểm tổ chức buổi hòa nhạc."}]},{"id":"kanzen_04","displayName":"Chuyên đề 4: Luyện bẫy Dấu sao ★ (Sắp xếp câu)","subtitle":"20 câu • Mondai 8 (組み立て)","badge":"Dấu sao ★","questions":[{"mondai":8,"q":1,"prompt":"詳しい話を ＿＿＿　＿＿＿　★　＿＿＿ 判断できない。","options":["正しいかは","聞かない","どちらが","ことには、"],"answer":3,"word_explain":"Thứ tự đúng: 2 → 4 → ★3 → 1 | Cấu trúc: 〜ないことには〜ない (Nếu không... thì không...). Cụm đầy đủ: 詳しい話を聞かないことには、どちらが正しいかは判断できない。Lưu ý động từ thể phủ định 「聞かない」 nối trực tiếp với 「ことには」.","translation_vi":"Nếu không nghe câu chuyện chi tiết thì không thể phán đoán xem bên nào đúng."},{"mondai":8,"q":2,"prompt":"経験が豊富だ ＿＿＿　★　＿＿＿　＿＿＿ わけではない。","options":["うまくこなせる","からといって、","という","すべての仕事を"],"answer":4,"word_explain":"Thứ tự đúng: 2 → ★4 → 1 → 3 | Cấu trúc: 〜からといって〜というわけではない (Không hẳn chỉ vì... mà...). Cụm đầy đủ: 経験が豊富だからといって、すべての仕事をうまくこなせるというわけではない。Lưu ý cặp hô ứng 「からといって」 đi với phủ định bộ phận 「というわけではない」.","translation_vi":"Không hẳn cứ có kinh nghiệm phong phú là có thể xử lý trôi chảy mọi công việc."},{"mondai":8,"q":3,"prompt":"彼は日本に ＿＿＿　＿＿＿　★　＿＿＿ 自然だ。","options":["にしては、","会話がとても","来て","まだ半年"],"answer":1,"word_explain":"Thứ tự đúng: 3 → 4 → ★1 → 2 | Cấu trúc: 〜にしては (So với tiêu chuẩn của... thì lại...). Cụm đầy đủ: 彼は日本に来てまだ半年にしては、会話がとても自然だ。Lưu ý 「まだ半年」 là mốc tiêu chuẩn để nối với 「にしては」.","translation_vi":"So với việc mới đến Nhật được nửa năm, khả năng hội thoại của anh ấy rất tự nhiên."},{"mondai":8,"q":4,"prompt":"今は大きなプロジェクトの ＿＿＿　＿＿＿　★　＿＿＿ ない。","options":["どころでは","締め切りが","旅行に行く","迫っていて、"],"answer":3,"word_explain":"Thứ tự đúng: 2 → 4 → ★3 → 1 | Cấu trúc: Vる + どころではない (Không phải lúc để... / Còn lâu mới...). Cụm đầy đủ: 今は大きなプロジェクトの締め切りが迫っていて、旅行に行くどころではない。Lưu ý 「プロジェクトの」 phải đi với danh từ 「締め切りが」.","translation_vi":"Hiện tại hạn chót của dự án lớn đang đến gần, không phải lúc để đi du lịch."},{"mondai":8,"q":5,"prompt":"もし時間を ＿＿＿　★　＿＿＿　＿＿＿ やり直したい。","options":["選択を","ものなら、","戻せる","あのときの"],"answer":2,"word_explain":"Thứ tự đúng: 3 → ★2 → 4 → 1 | Cấu trúc: V(khả năng) + ものなら (Nếu có thể... thì thật muốn...). Cụm đầy đủ: もし時間を戻せるものなら、あのときの選択をやり直したい。Lưu ý 「ものなら」 nối sau động từ thể khả năng 「戻せる」 để diễn tả mong ước khó thành hiện thực.","translation_vi":"Nếu có thể quay ngược thời gian, tôi muốn làm lại sự lựa chọn lúc đó."},{"mondai":8,"q":6,"prompt":"新しいビルの ＿＿＿　＿＿＿　★　＿＿＿ 深まっている。","options":["対立が","めぐって、","賛成派と反対派の","建設を"],"answer":3,"word_explain":"Thứ tự đúng: 4 → 2 → ★3 → 1 | Cấu trúc: N + をめぐって (Xoay quanh vấn đề...). Cụm đầy đủ: 新しいビルの建設をめぐって、賛成派と反対派の対立が深まっている。Lưu ý 「〜をめぐって」 thường đi với các từ chỉ tranh luận, đối lập như 「対立が深まっている」.","translation_vi":"Xoay quanh việc xây dựng tòa nhà mới, sự đối lập giữa phe ủng hộ và phe phản đối đang ngày càng sâu sắc."},{"mondai":8,"q":7,"prompt":"大雪で交通機関が ＿＿＿　★　＿＿＿　＿＿＿ 得なくなった。","options":["出張を","予定していた","止まってしまい、","中止せざるを"],"answer":2,"word_explain":"Thứ tự đúng: 3 → ★2 → 1 → 4 | Cấu trúc: Vない(bỏ ない) + ざるを得ない / する → せざるを得ない (Đành phải...). Cụm đầy đủ: 大雪で交通機関が止まってしまい、予定していた出張を中止せざるを得なくなった。Lưu ý bẫy động từ nhóm 3 「中止する」 biến đổi thành 「中止せざるを」.","translation_vi":"Vì tuyết rơi dày làm các phương tiện giao thông ngừng hoạt động, tôi đành phải hủy chuyến công tác đã lên kế hoạch."},{"mondai":8,"q":8,"prompt":"このパソコンは ＿＿＿　＿＿＿　★　＿＿＿ 充実している。","options":["わりに、","価格が","機能が","手ごろな"],"answer":1,"word_explain":"Thứ tự đúng: 2 → 4 → ★1 → 3 | Cấu trúc: Aな + わりに (Tuy... nhưng lại / So với... thì...). Cụm đầy đủ: このパソコンは価格が手ごろなわりに、機能が充実している。Lưu ý kết hợp từ cố định 「価格が手ごろだ」 và 「機能が充実している」.","translation_vi":"Chiếc máy tính này tuy giá cả phải chăng nhưng tính năng lại rất đầy đủ."},{"mondai":8,"q":9,"prompt":"交渉の ＿＿＿　＿＿＿　★　＿＿＿ いない。","options":["かけては、","右に出る者は","うまさに","社内で彼女の"],"answer":4,"word_explain":"Thứ tự đúng: 3 → 1 → ★4 → 2 | Cấu trúc: N + にかけては (Về khoản / Xét về mặt... thì giỏi nhất). Cụm đầy đủ: 交渉のうまさにかけては、社内で彼女の右に出る者はいない。Lưu ý thành ngữ 「〜の右に出る者はいない」 (không ai sánh bằng).","translation_vi":"Xét về sự khéo léo trong đàm phán, trong công ty không ai có thể sánh bằng cô ấy."},{"mondai":8,"q":10,"prompt":"海外旅行の前には、 ＿＿＿　★　＿＿＿　＿＿＿ ない。","options":["保険に入っておく","トラブルに備えて","に越したことは","万が一の"],"answer":2,"word_explain":"Thứ tự đúng: 4 → ★2 → 1 → 3 | Cấu trúc: Vる + に越したことはない (Tốt nhất là... / Không gì hơn là...). Cụm đầy đủ: 海外旅行の前には、万が一のトラブルに備えて保険に入っておくに越したことはない。Lưu ý cụm cố định 「万が一のトラブルに備えて」 (đề phòng rắc rối bất trắc).","translation_vi":"Trước khi đi du lịch nước ngoài, tốt nhất là nên mua bảo hiểm để đề phòng những rắc rối bất trắc."},{"mondai":8,"q":11,"prompt":"このプロジェクトが ＿＿＿　＿＿＿　★　＿＿＿ 言える。","options":["次第だと","成功するか","チームの協力","どうかは、"],"answer":3,"word_explain":"Thứ tự đúng: 2 → 4 → ★3 → 1 | Cấu trúc: N + 次第だ (Tùy thuộc vào...). Cụm đầy đủ: このプロジェクトが成功するかどうかは、チームの協力次第だと言える。Lưu ý tách đúng cụm 「成功するかどうかは」 trước rồi mới đến 「チームの協力次第だと」.","translation_vi":"Có thể nói việc dự án này có thành công hay không tùy thuộc vào sự hợp tác của cả nhóm."},{"mondai":8,"q":12,"prompt":"締め切りを ＿＿＿　＿＿＿　★　＿＿＿ 逃してしまった。","options":["ばかりに、","していた","せっかくの機会を","一日勘違い"],"answer":1,"word_explain":"Thứ tự đúng: 4 → 2 → ★1 → 3 | Cấu trúc: Vた + ばかりに (Chỉ vì... mà dẫn đến kết quả đáng tiếc). Cụm đầy đủ: 締め切りを一日勘違いしていたばかりに、せっかくの機会を逃してしまった。Lưu ý vế sau luôn là kết quả tiêu cực, hối tiếc.","translation_vi":"Chỉ vì nhầm lẫn hạn chót một ngày mà tôi đã đánh mất cơ hội quý giá."},{"mondai":8,"q":13,"prompt":"いくら眠くても、 ＿＿＿　★　＿＿＿　＿＿＿ わけにはいかない。","options":["レポートなので、","今夜は寝る","明日までに","提出しなければならない"],"answer":4,"word_explain":"Thứ tự đúng: 3 → ★4 → 1 → 2 | Cấu trúc: Vる + わけにはいかない (Không thể làm... vì trách nhiệm/hoàn cảnh). Cụm đầy đủ: いくら眠くても、明日までに提出しなければならないレポートなので、今夜は寝るわけにはいかない。Lưu ý mệnh đề bổ nghĩa 「明日までに提出しなければならない」 đứng ngay trước danh từ 「レポート」.","translation_vi":"Dù có buồn ngủ đến mấy, vì đây là báo cáo phải nộp trước ngày mai nên tối nay tôi không thể đi ngủ được."},{"mondai":8,"q":14,"prompt":"さっきまで ＿＿＿　＿＿＿　★　＿＿＿ 雨はやんだ。","options":["嘘のように","かと思ったら、","あんなに","激しく降っていた"],"answer":2,"word_explain":"Thứ tự đúng: 3 → 4 → ★2 → 1 | Cấu trúc: Vた + かと思ったら (Vừa mới... thì đã chuyển biến ngay lập tức). Cụm đầy đủ: さっきまであんなに激しく降っていたかと思ったら、嘘のように雨はやんだ。Lưu ý 「嘘のように」 bổ nghĩa cho động từ 「やんだ」 ở cuối câu.","translation_vi":"Vừa mới lúc nãy mưa còn rơi dữ dội như thế, vậy mà thoắt cái đã tạnh như chưa từng có chuyện gì."},{"mondai":8,"q":15,"prompt":"新製品の ＿＿＿　★　＿＿＿　＿＿＿ 行われた。","options":["先立って、","体験会が","発売に","記者向けの"],"answer":1,"word_explain":"Thứ tự đúng: 3 → ★1 → 4 → 2 | Cấu trúc: N + に先立って (Trước khi diễn ra một sự kiện quan trọng). Cụm đầy đủ: 新製品の発売に先立って、記者向けの体験会が行われた。Lưu ý 「新製品の」 nối với 「発売に」, còn 「記者向けの」 nối với 「体験会が」.","translation_vi":"Trước khi mở bán sản phẩm mới, một buổi trải nghiệm dành cho các phóng viên đã được tổ chức."},{"mondai":8,"q":16,"prompt":"彼は謝る ＿＿＿　＿＿＿　★　＿＿＿ し始めた。","options":["ミスを","どころか、","人のせいに","自分の"],"answer":1,"word_explain":"Thứ tự đúng: 2 → 4 → ★1 → 3 | Cấu trúc: Vる + どころか (Chẳng những không... mà trái lại còn...). Cụm đầy đủ: 彼は謝るどころか、自分のミスを人のせいにし始めた。Lưu ý cấu trúc 「〜を人のせいにする」 (đổ lỗi cho người khác).","translation_vi":"Chẳng những không xin lỗi, anh ta còn bắt đầu đổ lỗi sai của mình cho người khác."},{"mondai":8,"q":17,"prompt":"インターネットの ＿＿＿　＿＿＿　★　＿＿＿ 大きく変わった。","options":["集め方も","普及に","人々の情報の","伴って、"],"answer":3,"word_explain":"Thứ tự đúng: 2 → 4 → ★3 → 1 | Cấu trúc: N + に伴って (Cùng với sự biến đổi của... thì...). Cụm đầy đủ: インターネットの普及に伴って、人々の情報の集め方も大きく変わった。Lưu ý chuỗi danh từ nối bằng 「の」: 「人々の情報の集め方も」.","translation_vi":"Cùng với sự phổ biến của internet, cách thu thập thông tin của mọi người cũng đã thay đổi lớn."},{"mondai":8,"q":18,"prompt":"この研究は、医学の歴史を ＿＿＿　★　＿＿＿　＿＿＿ 大発見だ。","options":["過言では","と言っても","ないほどの","塗り替えた"],"answer":2,"word_explain":"Thứ tự đúng: 4 → ★2 → 1 → 3 | Cấu trúc: 〜と言っても過言ではない (Nói rằng... cũng không hề quá lời). Cụm đầy đủ: この研究は、医学の歴史を塗り替えたと言っても過言ではないほどの大発見だ。Lưu ý cụm 「歴史を塗り替える」 (viết lại lịch sử) và dạng định ngữ 「〜ないほどの + N」.","translation_vi":"Nghiên cứu này là một phát hiện vĩ đại đến mức nói rằng nó đã viết lại lịch sử y học cũng không hề quá lời."},{"mondai":8,"q":19,"prompt":"このまま対策を ＿＿＿　＿＿＿　★　＿＿＿ ある。","options":["流出する","おそれが","怠れば、","個人情報が"],"answer":1,"word_explain":"Thứ tự đúng: 3 → 4 → ★1 → 2 | Cấu trúc: Vる + おそれがある (Có nguy cơ / Lo ngại rằng...). Cụm đầy đủ: このまま対策を怠れば、個人情報が流出するおそれがある。Lưu ý ngoại động từ 「対策を怠る」 và nội động từ 「個人情報が流出する」.","translation_vi":"Nếu cứ lơ là các biện pháp đối phó như thế này, có nguy cơ thông tin cá nhân sẽ bị rò rỉ."},{"mondai":8,"q":20,"prompt":"あまりにも ＿＿＿　★　＿＿＿　＿＿＿ 逃してしまった。","options":["ものだから、","話が","つい終電を","面白かった"],"answer":4,"word_explain":"Thứ tự đúng: 2 → ★4 → 1 → 3 | Cấu trúc: 〜ものだから (Tại vì... nên — dùng để giải thích/biện minh cho kết quả ngoài ý muốn). Cụm đầy đủ: あまりにも話が面白かったものだから、つい終電を逃してしまった。Lưu ý cặp hô ứng 「あまりにも〜ものだから、つい〜てしまった」.","translation_vi":"Tại vì câu chuyện thú vị quá mức nên tôi đã lỡ mất chuyến tàu cuối."}]},{"id":"kanzen_05","displayName":"Chuyên đề 5: Bẫy Từ vựng văn cảnh, Phó từ & Động từ ghép","subtitle":"20 câu • Mondai 4 (Shin Kanzen 語彙)","badge":"Từ vựng","questions":[{"mondai":4,"q":1,"prompt":"お忙しいところ、(　　)遠くまでお越しいただき、誠にありがとうございます。","options":["せっかく","わざわざ","わざと","なにとぞ"],"answer":2,"word_explain":"わざわざ: cất công, cố tình bỏ công sức làm việc gì (thường dùng để cảm ơn sự vất vả của đối phương). Khác với せっかく (công sức/cơ hội quý giá, hay đi với のに/だから) và わざと (cố ý làm điều xấu/trêu chọc).","translation_vi":"Giữa lúc bận rộn mà ngài đã cất công lặn lội từ xa đến đây, tôi xin chân thành cảm ơn."},{"mondai":4,"q":2,"prompt":"限定スイーツの販売が始まると、用意した500個は(　　)売り切れてしまった。","options":["たちまち","みるみる","じっくり","たっぷり"],"answer":1,"word_explain":"たちまち: trong chớp mắt, thoáng chốc (chỉ sự việc xảy ra hoặc hoàn tất cực nhanh). Khác với みるみる (thay đổi rõ rệt trước mắt theo tiến trình liên tục, thường đi với 〜ていく).","translation_vi":"Ngay khi mở bán món bánh ngọt phiên bản giới hạn, 500 chiếc chuẩn bị sẵn đã bán hết veo trong nháy mắt."},{"mondai":4,"q":3,"prompt":"今月は仕事が忙しく、手帳には予定が(　　)書き込まれている。","options":["すっかり","ぴったり","ぎっしり","ぐっすり"],"answer":3,"word_explain":"ぎっしり: dày đặc, kín mít không còn chỗ trống (dùng cho lịch trình, đồ vật xếp chặt). Khác với すっかり (hoàn toàn), ぴったり (vừa khít/đúng lúc), ぐっすり (ngủ say).","translation_vi":"Tháng này công việc bận rộn, trong sổ tay lịch trình được ghi kín mít."},{"mondai":4,"q":4,"prompt":"締め切りに追われて、ここ数日は(　　)睡眠もとれていない。","options":["めったに","さっぱり","ちっとも","ろくに"],"answer":4,"word_explain":"ろくに（〜ない）: không ra hồn, không đầy đủ/tử tế (mang sắc thái bất mãn). Khác với めったに〜ない (hiếm khi), さっぱり〜ない (hoàn toàn không), ちっとも〜ない (chẳng chút nào).","translation_vi":"Vì bị hạn chót dí sát nút nên mấy ngày gần đây tôi thậm chí còn không ngủ được tử tế."},{"mondai":4,"q":5,"prompt":"契約書にサインをしてしまったのだから、(　　)後悔しても仕方がない。","options":["いまにも","いまさら","いまだに","いますぐ"],"answer":2,"word_explain":"いまさら: đến nước này, giờ đã quá muộn (thường đi với 〜ても仕方がない / 〜ても遅い). Khác với いまにも (sắp sửa ngay lập tức) và いまだに (đến tận bây giờ vẫn).","translation_vi":"Vì đã lỡ ký vào bản hợp đồng rồi nên giờ này có hối hận cũng vô ích thôi."},{"mondai":4,"q":6,"prompt":"山頂から見た朝日のあまりの美しさに、(　　)息をのんだ。","options":["つい","うっかり","思わず","わざと"],"answer":3,"word_explain":"思わず（おもわず）: bất giác, theo phản xạ tự nhiên do xúc động hoặc bất ngờ (hay đi với 息をのむ, 声をあげる, 笑う). Khác với つい (lỡ làm dù biết không nên) và うっかり (đãng trí, sơ ý quên).","translation_vi":"Trước vẻ đẹp quá đỗi của ánh bình minh nhìn từ đỉnh núi, tôi bất giác nín thở."},{"mondai":4,"q":7,"prompt":"この会議室は狭いので、入れても(　　)10人くらいだろう。","options":["せいぜい","どうせ","せめて","なんとか"],"answer":1,"word_explain":"せいぜい: nhiều nhất là, tối đa là (giới hạn trên khi đánh giá thấp). Khác với せめて (ít nhất là, mang ý mong muốn) và どうせ (đằng nào thì cũng).","translation_vi":"Phòng họp này hẹp nên có nhét vào cũng chỉ được tối đa khoảng 10 người thôi."},{"mondai":4,"q":8,"prompt":"お探しの商品は、(　　)ただいま在庫を切らしております。","options":["さすがに","さいわい","案の定","あいにく"],"answer":4,"word_explain":"あいにく: thật không may, rất tiếc là (dùng khi sự việc không như mong đợi, rất hay gặp trong văn phong tiếp khách lịch sự). Khác với さすがに (quả nhiên là / dù sao đi nữa).","translation_vi":"Sản phẩm quý khách đang tìm hiện tại rất tiếc là đang hết hàng trong kho ạ."},{"mondai":4,"q":9,"prompt":"市役所は市民に対して、節電への協力を(　　)いる。","options":["呼びだして","呼びかけて","呼びこんで","呼びなおして"],"answer":2,"word_explain":"呼びかける（よびかける）: kêu gọi, phát động (hướng tác động tới đối tượng, cấu trúc 〜かける). Cụm cố định: 協力を呼びかける (kêu gọi sự hợp tác). Khác với 呼びだす (gọi ra gặp riêng).","translation_vi":"Ủy ban thành phố đang kêu gọi người dân hợp tác tiết kiệm điện."},{"mondai":4,"q":10,"prompt":"初めてのフルマラソンだったが、最後まであきらめずに42.195キロを(　　)。","options":["走りかけた","走りだした","走りきった","走りなおした"],"answer":3,"word_explain":"走りきる（はしりきる）: chạy trọn vẹn đến hết quãng đường (〜きる diễn tả sự hoàn thành triệt để từ đầu đến cuối). Khác với 走りかける (mới bắt đầu chạy/chạy dở) và 走りだす (bắt đầu chạy).","translation_vi":"Đây là lần đầu tiên tôi chạy marathon toàn phần, nhưng tôi đã không bỏ cuộc cho đến cuối cùng và chạy trọn vẹn 42,195 km."},{"mondai":4,"q":11,"prompt":"長い間(　　)末に、ついに自分の店を開く決心をした。","options":["考えぬいた","考えかけた","考えだした","考えついた"],"answer":1,"word_explain":"考えぬく（かんがえぬく）: suy nghĩ thấu đáo đến tận cùng (〜ぬく nhấn mạnh sự kiên trì làm đến cùng dù khó khăn). Khác với 考えだす (nghĩ ra/phát minh) và 考えつく (nảy ra ý tưởng).","translation_vi":"Sau một thời gian dài suy nghĩ thấu đáo đến cùng, cuối cùng tôi đã quyết tâm mở cửa hàng của riêng mình."},{"mondai":4,"q":12,"prompt":"懐かしい同級生と喫茶店で(　　)、気がついたらもう夕方になっていた。","options":["話しだして","話しきって","話しなおして","話しこんで"],"answer":4,"word_explain":"話しこむ（はなしこむ）: mải mê trò chuyện, chìm đắm vào cuộc nói chuyện (〜こむ chỉ trạng thái đi sâu, tập trung vào một hành động). Phù hợp với bối cảnh quên cả thời gian.","translation_vi":"Mải mê trò chuyện với người bạn cùng lớp lâu ngày gặp lại ở quán cà phê, đến lúc để ý thì trời đã tối sầm."},{"mondai":4,"q":13,"prompt":"提出したレポートに計算ミスが見つかったので、最初から(　　)ことになった。","options":["やりきる","やりなおす","やりだす","やりあげる"],"answer":2,"word_explain":"やりなおす: làm lại từ đầu (〜なおす mang nghĩa thực hiện lại hành động để sửa sai hoặc làm cho tốt hơn). Hợp lý với ngữ cảnh phát hiện sai sót.","translation_vi":"Vì phát hiện lỗi tính toán trong báo cáo đã nộp nên tôi đành phải làm lại từ đầu."},{"mondai":4,"q":14,"prompt":"締め切り直前までかかったが、なんとか論文を(　　)ことができた。","options":["書きだす","書きあう","書きあげる","書きかける"],"answer":3,"word_explain":"書きあげる（かきあげる）: viết hoàn chỉnh, hoàn tất một tác phẩm/luận văn (〜あげる nhấn mạnh hoàn thành thành phẩm). Khác với 書きかける (viết dở dang) và 書きあう (viết cho nhau).","translation_vi":"Dù mất thời gian đến tận sát hạn chót, cuối cùng tôi cũng xoay xở viết xong được luận văn."},{"mondai":4,"q":15,"prompt":"事故の原因を正確に(　　)するため、現場の調査が進められている。","options":["把握","維持","発揮","普及"],"answer":1,"word_explain":"把握（はあく）: nắm bắt, hiểu rõ tình hình/nguyên nhân. Cụm từ N2 rất hay thi: 原因を把握する (nắm bắt nguyên nhân), 状況を把握する (nắm bắt tình hình).","translation_vi":"Để nắm bắt chính xác nguyên nhân vụ tai nạn, công tác điều tra hiện trường đang được tiến hành."},{"mondai":4,"q":16,"prompt":"普段の練習の成果を本番で十分に(　　)できるように、体調を整えている。","options":["維持","普及","発揮","回復"],"answer":3,"word_explain":"発揮（はっき）: phát huy (năng lực, sức mạnh, thành quả). Cụm từ cố định: 成果を発揮する / 実力を発揮する. Khác với 維持 (duy trì) và 普及 (phổ cập).","translation_vi":"Tôi đang điều chỉnh thể trạng để có thể phát huy trọn vẹn thành quả luyện tập hàng ngày trong buổi thi chính thức."},{"mondai":4,"q":17,"prompt":"スマートフォンの(　　)に伴い、現金を使わずに買い物をする人が急増した。","options":["維持","普及","対策","傾向"],"answer":2,"word_explain":"普及（ふきゅう）: sự phổ cập, lan rộng (công nghệ, thiết bị, tập quán trong xã hội). Rất hay đi với ngữ pháp N2 〜に伴い (cùng với sự...).","translation_vi":"Cùng với sự phổ cập của điện thoại thông minh, số người mua sắm không dùng tiền mặt đã tăng vọt."},{"mondai":4,"q":18,"prompt":"科学的な(　　)のない噂をうのみにしてはいけない。","options":["対策","規模","傾向","根拠"],"answer":4,"word_explain":"根拠（こんきょ）: căn cứ, cơ sở (để chứng minh một nhận định). Cụm từ cố định: 科学的な根拠 (căn cứ khoa học), 根拠のない噂 (tin đồn vô căn cứ).","translation_vi":"Không được tin răm rắp vào những tin đồn không có căn cứ khoa học."},{"mondai":4,"q":19,"prompt":"最近の若者は、テレビよりもインターネットでニュースを見る(　　)がある。","options":["傾向","規模","根拠","対策"],"answer":1,"word_explain":"傾向（けいこう）: khuynh hướng, xu hướng. Cấu trúc kinh điển ở N2: 〜する傾向がある (có xu hướng làm gì). Khác với 対策 (đối sách) và 規模 (quy mô).","translation_vi":"Giới trẻ gần đây có xu hướng xem tin tức trên internet hơn là trên tivi."},{"mondai":4,"q":20,"prompt":"今回の地震は予想以上の(　　)で、広い地域に大きな被害をもたらした。","options":["維持","対策","普及","規模"],"answer":4,"word_explain":"規模（きぼ）: quy mô, tầm cỡ (của sự kiện, công trình, thiên tai). Cụm hay gặp: 予想以上の規模 (quy mô ngoài dự đoán), 規模が大きい (quy mô lớn).","translation_vi":"Trận động đất lần này có quy mô vượt ngoài dự đoán, gây ra thiệt hại lớn trên một khu vực rộng."}]},{"id":"kanzen_06","displayName":"Chuyên đề 6: Bẫy Đồng nghĩa & Cách dùng từ (M5 & M6)","subtitle":"20 câu • 10 câu Mondai 5 + 10 câu Mondai 6","badge":"Đồng nghĩa & Cách dùng","questions":[{"mondai":5,"q":1,"prompt":"久しぶりに会った高校の同級生は、<u>相変わらず</u>元気そうだった。","options":["想像していた以上に","思ったよりもずっと","以前と同じように","以前とは違って"],"answer":3,"word_explain":"相変わらず (あいかわらず) = 以前と同じように: vẫn như trước, không thay đổi","translation_vi":"Người bạn cùng lớp cấp ba lâu ngày mới gặp trông vẫn khỏe khoắn như trước."},{"mondai":5,"q":2,"prompt":"急いでいたので、<u>うっかり</u>財布を家に忘れてきてしまった。","options":["不注意で","わざと","いつの間にか","思わず"],"answer":1,"word_explain":"うっかり (うっかり) = 不注意で: vô ý, lơ đễnh, sơ suất","translation_vi":"Vì vội nên tôi đã vô ý để quên ví ở nhà mất rồi."},{"mondai":5,"q":3,"prompt":"専門用語が多くて、その論文の内容は<u>さっぱり</u>わからなかった。","options":["あまり","ほとんど","なかなか","まったく"],"answer":4,"word_explain":"さっぱり (さっぱり) = まったく: hoàn toàn (không)","translation_vi":"Vì có nhiều thuật ngữ chuyên ngành nên tôi hoàn toàn không hiểu nội dung bài luận văn đó."},{"mondai":5,"q":4,"prompt":"台風が近づいているため、週末の運動会は来週に<u>延期する</u>ことになった。","options":["予定を取り消す","予定を遅らせる","予定を早める","予定を変更しない"],"answer":2,"word_explain":"延期する (えんきする) = 予定を遅らせる: hoãn lại, dời lịch sang sau","translation_vi":"Do bão đang đến gần nên hội thao cuối tuần đã được quyết định hoãn sang tuần sau."},{"mondai":5,"q":5,"prompt":"そんな<u>くだらない</u>ことでけんかをするのはやめたほうがいい。","options":["意味のない","許せない","深刻な","複雑な"],"answer":1,"word_explain":"くだらない (くだらない) = 意味のない: vô nghĩa, vớ vẩn, tầm phào","translation_vi":"Tốt hơn là đừng cãi nhau vì những chuyện vớ vẩn như thế."},{"mondai":5,"q":6,"prompt":"健康を<u>維持する</u>ためには、毎日の適度な運動とバランスのよい食事が大切だ。","options":["取り戻す","高める","保つ","確認する"],"answer":3,"word_explain":"維持する (いじする) = 保つ: duy trì, giữ vững","translation_vi":"Để duy trì sức khỏe thì việc vận động điều độ mỗi ngày và chế độ ăn cân bằng là rất quan trọng."},{"mondai":5,"q":7,"prompt":"初対面なのにいきなりお金を貸してくれと言うなんて、本当に<u>図々しい</u>人だ。","options":["気が弱い","遠慮がない","責任感がない","落ち着きがない"],"answer":2,"word_explain":"図々しい (ずうずうしい) = 遠慮がない: trơ tráo, mặt dày, không biết ngại","translation_vi":"Mới gặp lần đầu mà đột nhiên hỏi vay tiền, đúng là người mặt dày thật."},{"mondai":5,"q":8,"prompt":"新しいプロジェクトを始める前に、現在の市場の動向をしっかり<u>把握して</u>おく必要がある。","options":["予想して","説明して","報告して","理解して"],"answer":4,"word_explain":"把握する (はあくする) = 理解する: nắm bắt, hiểu rõ","translation_vi":"Trước khi bắt đầu dự án mới, cần phải nắm bắt kỹ xu hướng thị trường hiện tại."},{"mondai":5,"q":9,"prompt":"この地域は冬でも温暖なので、雪が降ることは<u>めったに</u>ない。","options":["ほとんど","決して","少しも","なかなか"],"answer":1,"word_explain":"めったに (めったに) = ほとんど: hiếm khi, hầu như (không)","translation_vi":"Khu vực này ngay cả mùa đông cũng ấm áp nên hiếm khi có tuyết rơi."},{"mondai":5,"q":10,"prompt":"作業を効率化するために、無駄な手続きを<u>省く</u>ことにした。","options":["増やす","変える","取り除く","見直す"],"answer":3,"word_explain":"省く (はぶく) = 取り除く: lược bỏ, cắt giảm, loại bỏ","translation_vi":"Để nâng cao hiệu suất công việc, chúng tôi đã quyết định lược bỏ các thủ tục rườm rà."},{"mondai":6,"q":11,"prompt":"妥協","options":["自分のミスを認めて、上司に<u>妥協</u>した。","お互いの意見が対立していたが、少しずつ<u>妥協</u>して合意に達した。","地域の発展のために、住民全員で<u>妥協</u>して清掃活動を行った。","長年の問題がようやく<u>妥協</u>して、みんな安心した。"],"answer":2,"word_explain":"妥協 (だきょう): sự thỏa hiệp, nhượng bộ — dùng khi hai bên bất đồng cùng nhượng bộ để đạt thỏa thuận (hoặc hạ tiêu chuẩn xuống); câu 2 dùng đúng ngữ cảnh đàm phán.","translation_vi":"Ý kiến của hai bên đối lập nhau, nhưng nhờ nhượng bộ từng chút một mà đã đạt được thỏa thuận."},{"mondai":6,"q":12,"prompt":"配慮","options":["明日の試験に合格できるかどうか、とても<u>配慮</u>している。","この道は車が多いので、横断するときは左右に<u>配慮</u>してください。","大切な約束を忘れないように、手帳に<u>配慮</u>しておいた。","このホテルは、高齢者や小さな子ども連れの客にも<u>配慮</u>した設備が整っている。"],"answer":4,"word_explain":"配慮 (はいりょ): sự quan tâm, chu đáo, cân nhắc đến hoàn cảnh/cảm nhận của người khác — đi với trợ từ に (～に配慮する); câu 4 dùng đúng nghĩa quan tâm đến đối tượng khách hàng.","translation_vi":"Khách sạn này có đầy đủ trang thiết bị được thiết kế chu đáo cho cả người cao tuổi và khách đi cùng trẻ nhỏ."},{"mondai":6,"q":13,"prompt":"油断","options":["前半で大きくリードしていたが、少し<u>油断</u>したすきに逆転されてしまった。","どうぞ<u>油断</u>せずに、好きなだけ召し上がってください。","仕事が全部終わったので、今夜はゆっくり<u>油断</u>して休みたい。","体調が悪いため、今回の大会への出場は<u>油断</u>することにした。"],"answer":1,"word_explain":"油断 (ゆだん): sự chủ quan, lơ là cảnh giác — chỉ trạng thái mất cảnh giác dẫn đến thất bại hoặc nguy hiểm; câu 1 dùng đúng sắc thái chủ quan nên bị lội ngược dòng.","translation_vi":"Hiệp một chúng tôi dẫn trước rất xa, nhưng chỉ vì một phút chủ quan mà đã bị lội ngược dòng mất."},{"mondai":6,"q":14,"prompt":"手頃","options":["山田さんは性格が<u>手頃</u>なので、誰とでもすぐに仲良くなれる。","今日は天気も<u>手頃</u>だし、公園へ散歩に行こう。","駅前の新しいレストランは、値段が<u>手頃</u>でおいしいと評判だ。","会議には<u>手頃</u>な時間に到着したので、準備をする余裕があった。"],"answer":3,"word_explain":"手頃 (てごろ): vừa phải, hợp lý, phải chăng — thường dùng cho giá cả (値段), kích cỡ (大きさ), mức độ; câu 3 dùng đúng cụm \"値段が手頃\".","translation_vi":"Nhà hàng mới trước nhà ga nổi tiếng là giá cả phải chăng mà lại ngon."},{"mondai":6,"q":15,"prompt":"素直","options":["この道を<u>素直</u>に進むと、右手に郵便局が見えてきます。","先輩からの厳しいアドバイスを<u>素直</u>に受け入れて、やり方を改善した。","このスープは味が<u>素直</u>で、毎日飲んでも飽きない。","準備が整っていたので、イベントは最後まで<u>素直</u>に進行した。"],"answer":2,"word_explain":"素直 (すなお): thẳng thắn, ngoan ngoãn, biết lắng nghe — chỉ thái độ chân thành tiếp nhận lời khuyên hoặc cảm xúc, không bướng bỉnh; câu 2 dùng đúng cụm \"素直に受け入れる\".","translation_vi":"Tôi đã thẳng thắn tiếp thu lời khuyên nghiêm khắc của tiền bối và cải thiện cách làm."},{"mondai":6,"q":16,"prompt":"指摘","options":["特急電車に乗るため、窓側の席を<u>指摘</u>して予約した。","監督の<u>指摘</u>どおりに動いたら、試合に勝つことができた。","子どもが遠くの飛行機を<u>指摘</u>して、「あそこに飛んでいるよ」と言った。","提出前の報告書を見直してもらい、誤字やデータの誤りを<u>指摘</u>された。"],"answer":4,"word_explain":"指摘 (してき): sự chỉ ra (lỗi sai, khuyết điểm, vấn đề quan trọng) — không dùng cho việc chỉ tay hay chọn chỗ ngồi; câu 4 dùng đúng nghĩa chỉ ra lỗi sai.","translation_vi":"Tôi nhờ xem lại bản báo cáo trước khi nộp và đã được chỉ ra các lỗi chính tả cũng như sai sót về dữ liệu."},{"mondai":6,"q":17,"prompt":"余計","options":["<u>余計</u>な一言を言ってしまったせいで、彼を怒らせてしまった。","パーティーで<u>余計</u>になった料理は、みんなで分けて持ち帰った。","出発までまだ<u>余計</u>な時間があるから、カフェでコーヒーでも飲もう。","毎月の生活費に少し<u>余計</u>が出たので、貯金に回すことにした。"],"answer":1,"word_explain":"余計 (よけい): thừa thãi, không cần thiết (mang sắc thái tiêu cực) — thường dùng trong cụm \"余計な一言 / 余計な心配\"; câu 1 dùng đúng.","translation_vi":"Chỉ vì lỡ nói ra một câu thừa thãi mà tôi đã làm anh ấy nổi giận."},{"mondai":6,"q":18,"prompt":"物足りない","options":["レジで財布を見たら、会計するには500円<u>物足りなかった</u>。","参加者が多すぎて、会場のいすが10脚ほど<u>物足りない</u>。","この映画は映像はきれいだったが、ストーリーが単純すぎて少し<u>物足りなかった</u>。","せっかく招待していただいたのに、欠席してしまって本当に<u>物足りない</u>です。"],"answer":3,"word_explain":"物足りない (ものたりない): cảm thấy chưa đủ, hơi hụt hẫng, chưa thỏa mãn — dùng cho cảm giác chủ quan (vị nhạt, nội dung chưa sâu), không dùng cho sự thiếu hụt số lượng cụ thể; câu 3 dùng đúng.","translation_vi":"Bộ phim này hình ảnh thì đẹp nhưng cốt truyện quá đơn giản nên tôi thấy hơi hụt hẫng."},{"mondai":6,"q":19,"prompt":"きっかけ","options":["電車が止まったのが<u>きっかけ</u>で、今朝の会議に遅刻してしまった。","日本人の友人ができたことを<u>きっかけ</u>に、日本語の勉強を本格的に始めた。","この小説は<u>きっかけ</u>から終わりまで、ずっとハラハラする展開が続く。","問題を解決するためのいい<u>きっかけ</u>が思いつかず、困っている。"],"answer":2,"word_explain":"きっかけ (きっかけ): cơ hội, bước ngoặt, động lực khởi đầu — chỉ sự việc mở ra một hành động hoặc thay đổi mới (hay đi với ～をきっかけに); câu 2 dùng đúng.","translation_vi":"Nhân dịp kết bạn được với một người Nhật, tôi đã bắt đầu học tiếng Nhật một cách nghiêm túc."},{"mondai":6,"q":20,"prompt":"おっくう","options":["この荷物はとても<u>おっくう</u>なので、一人では二階まで運べない。","今年の入学試験の問題は、例年よりずっと<u>おっくう</u>だったそうだ。","隣の部屋から夜遅くまで音楽が聞こえてきて、とても<u>おっくう</u>だ。","寒い冬の朝は、暖かい布団から出るのが<u>おっくう</u>になる。"],"answer":4,"word_explain":"おっくう (億劫・おっくう): ngại, lười, thấy phiền phức không muốn làm — diễn tả tâm lý ngại bắt tay vào việc gì đó (hay đi với ～のがおっくうだ); câu 4 dùng đúng.","translation_vi":"Vào những buổi sáng mùa đông lạnh giá, tôi thấy thật ngại khi phải chui ra khỏi chiếc chăn ấm."}]}];
